select 'offer-modern-2br',x.name,x.description,1,x.method,true,x.owner,x.timing,x.pos from(values
('Room-by-room furnishing checklist','Complete furnishing requirements organized by room.','workspace','Furnishing Studio','Immediate',1),('Curated product selections','Hospitality-appropriate products and alternatives.','workspace','Furnishing Studio','Immediate',2),('Procurement checklist','Order and delivery tracking structure.','workspace','Furnishing Studio','Immediate',3),('Installation checklist','On-site completion and exception workflow.','workspace','Furnishing Studio','Immediate',4))x(name,description,method,owner,timing,pos) where not exists(select 1 from public.commerce_offer_deliverables where product_id='offer-modern-2br');
select id,'self_service','{"guestCheckout":true,"accountRequired":false,"propertyInformationRequired":true,"promoCodes":true,"termsAcceptance":true}'::jsonb from public.commerce_products on conflict(product_id)do nothing;
select id,name||' activation',case when product_type='subscription'then'subscription_created'else'payment_succeeded'end,'active'from public.commerce_products on conflict(product_id)do nothing;
select f.id,x.step_type,x.name,x.position,'{}'::jsonb from public.commerce_activation_flows f cross join(values('create_entitlement','Create entitlement',1),('notify_customer','Send confirmation and next steps',2))x(step_type,name,position)
where not exists(select 1 from public.commerce_activation_steps s where s.flow_id=f.id);
